        uid
        name

        root_labels: ~clusters {{
          uid
          name
          id
          label
          path
          category
          nodeType
          codeContent
          description
          level
          files
          fileContents

          functions {{
            uid
            name
            description
            line
          }}

          classes {{
            uid
            name
            description
            line

            methods {{
              uid
              name
              description
            }}
          }}

          variables {{
            uid
            name
            description
            line
          }}

          children: ~parents {{
            uid
            name
            nodeType
            level
          }}
        }}
      }}
    }}
    """

    result = self._execute_dgraph_query(query)

    if result and 'q' in result and result['q']:
