    """Vérifie si un élément a un nom RÉEL (non vide, non None)"""
    name = element.get('name')
    if not name:
        return False

    name = name.strip()
    if not name:
        return False

    # Rejeter les noms génériques/générés
    if name.startswith(('Unnamed', 'class-', 'func-', 'var-', 'method-')):
        return False

    return True

