def normalize_node_name(name: str) -> str:
    """
    Normalise le nom d'un nœud en enlevant l'extension et le chemin.

    Args:
        name: Nom complet du fichier/nœud

    Returns:
        Nom normalisé sans extension, ou None si invalide
    """
    if not name or not isinstance(name, str):
        return None

    name = name.strip()
    if not name or name.lower() == 'n/a':
        return None

    # Extraire le nom de base et enlever l'extension
    base = os.path.basename(name)
    name_without_ext = os.path.splitext(base)[0]

    return name_without_ext.strip() if name_without_ext.strip() else None


def get_supported_extensions() -> List[str]:
    """
    Retourne la liste des extensions supportées par le parser.

    Returns:
        Liste des extensions (ex: ['.py', '.java', '.js'])
    """
    parser = MultiLanguageDependencyParser()
    return list(parser.supported_languages.keys())


def is_supported_file(file_path: str) -> bool:
    """
    Vérifie si un fichier est supporté par le parser.

    Args:
        file_path: Chemin du fichier

    Returns:
        True si l'extension est supportée
    """
    ext = os.path.splitext(file_path)[1].lower()
    return ext in get_supported_extensions()

def test_full_scan(project_path: str):
    """
    Teste le scan complet d'un projet.

    Args:
        project_path: Chemin du projet à scanner
    """
    parser = MultiLanguageDependencyParser()
    scanner = ProjectStructureScanner(parser)

    logger.info(f"🔍 Début du scan COMPLET de {project_path}")

    # ✅ Scan sans limite de profondeur
    structure = scanner.scan_directory(project_path, max_depth=None)

    # Compter les éléments
    def count_elements(node, counts=None):
        if counts is None:
            counts = {'folders': 0, 'files': 0, 'total': 0}

        counts['total'] += 1
        if node.get('type') == 'folder':
            counts['folders'] += 1
        elif node.get('type') == 'file':
            counts['files'] += 1

        for child in node.get('children', []):
            count_elements(child, counts)

        return counts

    stats = {'folders': 0, 'files': 0, 'total': 0}
    for cluster in structure.get('clusters', []):
        count_elements(cluster, stats)

    logger.info(f"""
    ✅ Scan terminé !
    📊 Statistiques :
       - Dossiers : {stats['folders']}
       - Fichiers : {stats['files']}
       - Total éléments : {stats['total']}
    """)

    return structure"}

