    for match in re.finditer(var_pattern, content, re.MULTILINE):
        # Extraire noms multiples si destructuring
        names = re.findall(r'[\w_]+', match.group(1))
        for name in names:
            if name:
                variables.append({
                    'name': name,
                    'line': content[:match.start()].count('\n') + 1,
                    'type': 'var',
                    'scope': 'global',
                    'uid': f"var_{name}_approx"
                })
    return variables

