def _parse_python(self, content: str, file_path: str) -> Dict[str, List[Dict[str, Any]]]:
    relations = defaultdict(list)

    try:
        tree = ast.parse(content)
    except SyntaxError as e:
        logger.warning(f"Syntaxe Python invalide dans {file_path}: {e}, fallback regex.")
        return self._parse_generic(content, file_path)

    for node in ast.walk(tree):
        # Imports simples: import module
        if isinstance(node, ast.Import):
            for alias in node.names:
                target = alias.name.split('.')[0]
                relations['import'].append({
                    'target': target + '.py',
                    'target_uid': '',  # À mapper plus tard
                    'type': 'import',
                    'line': node.lineno,
                    'intra_file': False
                })

        # Imports relatifs: from module import name
        if isinstance(node, ast.Import):
            for alias in node.names:
                target = alias.name.split('.')[0] + '.py'
                relations['import'].append({
                    'target': target,
                    'target_uid': '',  # À mapper plus tard
                    'type': 'import',
                    'alias': alias.asname or None,
                    'line': node.lineno,
                    'intra_file': False
                })

        elif isinstance(node, ast.ImportFrom):
            module = node.module or ''
            for alias in node.names:
                target = (module + '.' + alias.name).split('.')[0] + '.py'
                relations['import'].append({
                    'target': target,
                    'target_uid': '',
                    'type': 'from_import',
                    'alias': alias.asname or alias.name,
                    'line': node.lineno,
                    'intra_file': False
                })

        # Héritage de classes
        elif isinstance(node, ast.ClassDef):
            for base in node.bases:
                if isinstance(base, ast.Name):
                    target = base.id
                    relations['heritage'].append({
                        'target': target,
                        'target_uid': f"class_{target}_approx",
                        'type': 'extends',
                        'line': node.lineno,
                        'intra_file': False
                    })

        # Appels de fonctions
        elif isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                target = node.func.id
                uid_target = f"func_{target}_{node.lineno}"
                relations['call'].append({
                    'target': target,
                    'target_uid': uid_target,
                    'type': 'function_call',
                    'line': node.lineno,
                    'intra_file': True  # Assumer intra pour simplicité
                })
            elif isinstance(node.func, ast.Attribute):
                if isinstance(node.func.value, ast.Name):
                    target = f"{node.func.value.id}.{node.func.attr}"
                    relations['call'].append({
                        'target': target,
                        'target_uid': '',
                        'type': 'method_call',
                        'line': node.lineno,
                        'intra_file': False
                    })

    # Détection usages de variables dans calls
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and any(isinstance(arg, ast.Name) for arg in node.args):
            for arg in node.args:
                if isinstance(arg, ast.Name):
                    relations['uses'].append({
                        'target': arg.id,
                        'target_uid': f"var_{arg.id}_{node.lineno}",
                        'type': 'variable_use',
                        'line': node.lineno,
                        'intra_file': True
                    })

    # Dédoublonner les relations
    return self._dedup_relations(relations)

def _dedup_relations(self, relations: defaultdict) -> Dict[str, List[Dict[str, Any]]]:
    """
    Dédoublonne les relations par target et type.

    Garde uniquement la première occurrence de chaque relation unique.

    Args:
        relations: defaultdict avec listes de relations

    Returns:
        Dictionnaire nettoyé sans doublons
    """
    for rel_type in relations:
        seen = {}
        deduped = []
        for rel in relations[rel_type]:
            key = (rel['target'], rel['type'], rel.get('intra_file', False))
            if key not in seen:
                seen[key] = rel
                deduped.append(rel)
        relations[rel_type] = deduped

    return dict(relations)

class MultiLanguageDependencyParser:
    """
    Parser multi-langages pour détecter les dépendances et relations.

    Supporte:
    - Python (.py)
    - Java (.java)
    - JavaScript/TypeScript (.js, .jsx, .ts, .tsx)
    - C/C++ (.c, .cpp, .h)

    Retourne un dictionnaire structuré des relations détectées:
    {
        'import': [{'target': 'fichier.py', 'type': 'import', 'line': 1}],
        'heritage': [{'target': 'ClasseParent', 'type': 'extends', 'line': 5}],
        'call': [{'target': 'fonction', 'type': 'function_call', 'line': 10}]
    }
    """

    def __init__(self):
        """Initialise le parser avec la mapping des langages supportés."""
        self.supported_languages = {
            '.py': self._parse_python,
            '.java': self._parse_java,
            '.js': self._parse_javascript,
            '.jsx': self._parse_javascript,
            '.ts': self._parse_javascript,
            '.tsx': self._parse_javascript,
            '.cpp': self._parse_cpp,
            '.c': self._parse_cpp,
            '.h': self._parse_cpp,
        }

    def parse_content(self, content: str, file_path: str) -> Dict[str, List[Dict[str, Any]]]:
        """
        Parse le contenu d'un fichier et retourne les relations détectées.

        Args:
            content: Contenu du fichier à parser
            file_path: Chemin du fichier (pour déterminer l'extension)

        Returns:
            Dictionnaire avec les relations groupées par type:
            {
                'import': [...],
                'heritage': [...],
                'call': [...],
                'uses': [...]  # Nouveau pour variables
            }
        """
        if not content:
            logger.warning(f"Contenu vide pour {file_path}")
            return {}

        ext = os.path.splitext(file_path)[1].lower()
        parser_func = self.supported_languages.get(ext)

        if not parser_func:
            logger.warning(f"Langage non supporté pour {ext}, utilisation de parsing générique.")
            return self._parse_generic(content, file_path)

        result = parser_func(content, file_path)
        total_rels = sum(len(v) for v in result.values())
        if total_rels > 0:
            logger.info(f"✅ {file_path}: {total_rels} relations parsées - {dict((k, len(v)) for k, v in result.items())}")
        else:
            logger.warning(f"⚠️ {file_path}: Aucune relation détectée")

            return result

        return parser_func(content, file_path)

    def extract_classes(self, content: str, file_path: str) -> List[Dict[str, Any]]:
        """
        Extrait les classes définies dans le fichier.

        Args:
            content: Contenu du fichier
            file_path: Chemin du fichier

        Returns:
            Liste des classes: [{'name': 'ClassName', 'line': 10, 'methods': [...], 'uid': '...'}]
        """
        ext = os.path.splitext(file_path)[1].lower()
        if ext == '.py':
            return self._extract_python_classes(content)
        elif ext == '.java':
            return self._extract_java_classes(content)
        elif ext in ['.js', '.jsx', '.ts', '.tsx']:
            return self._extract_js_classes(content)
        elif ext in ['.cpp', '.c', '.h']:
            return self._extract_cpp_classes(content)
        else:
            return []

    def extract_functions(self, content: str, file_path: str) -> List[Dict[str, Any]]:
        """
        Extrait les fonctions/méthodes définies dans le fichier.

        Args:
            content: Contenu du fichier
            file_path: Chemin du fichier

        Returns:
            Liste des fonctions: [{'name': 'funcName', 'line': 15, 'type': 'function/method', 'uid': '...', 'calls': [...]}]
        """
        ext = os.path.splitext(file_path)[1].lower()
        if ext == '.py':
            return self._extract_python_functions(content)
        elif ext == '.java':
            return self._extract_java_functions(content)
        elif ext in ['.js', '.jsx', '.ts', '.tsx']:
            return self._extract_js_functions(content)
        elif ext in ['.cpp', '.c', '.h']:
            return self._extract_cpp_functions(content)
        else:
            return []

    def extract_variables(self, content: str, file_path: str) -> List[Dict[str, Any]]:
        """
        Extrait les variables définies dans le fichier.

        Args:
            content: Contenu du fichier
            file_path: Chemin du fichier

        Returns:
            Liste des variables: [{'name': 'varName', 'line': 20, 'type': 'global/local/attribute', 'scope': 'class/function/global', 'uid': '...'}]
        """
        ext = os.path.splitext(file_path)[1].lower()
        if ext == '.py':
            return self._extract_python_variables(content)
        elif ext == '.java':
            return self._extract_java_variables(content)
        elif ext in ['.js', '.jsx', '.ts', '.tsx']:
            return self._extract_js_variables(content)
        elif ext in ['.cpp', '.c', '.h']:
            return self._extract_cpp_variables(content)
        else:
            return []

    def _extract_python_classes(self, content: str) -> List[Dict[str, Any]]:
        """✅ CORRIGÉ : Extrait classes AVEC code source"""
        classes = []

        try:
            tree = ast.parse(content)
            lines = content.split('\n')

            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef):
                    # ✅ EXTRACTION DU CODE SOURCE
                    start_line = node.lineno - 1

                    # Trouver la fin de la classe
                    end_line = start_line + 1
                    base_indent = len(lines[start_line]) - len(lines[start_line].lstrip())

                    while end_line < len(lines):
                        line = lines[end_line]

                        # Ligne vide ou commentaire : continuer
                        if not line.strip() or line.strip().startswith('#'):
                            end_line += 1
                            continue

                        # Si indentation <= base, c'est la fin
                        current_indent = len(line) - len(line.lstrip())
                        if current_indent <= base_indent:
                            break

                        end_line += 1

                    # ✅ EXTRAIRE LE CODE
                    code_content = '\n'.join(lines[start_line:end_line])

                    class_info = {
                        'name': node.name,
                        'line': node.lineno,
                        'methods': [],
                        'bases': [base.id if isinstance(base, ast.Name) else str(base) for base in node.bases],
                        'uid': f"class_{node.name}_{node.lineno}",
                        'uses_vars': [],
                        'codeContent': code_content  # ✅ AJOUTÉ
                    }

                    # Extraire méthodes AVEC code
                    for body_node in node.body:
                        if isinstance(body_node, ast.FunctionDef):
                            method_start = body_node.lineno - 1
                            method_end = method_start + 1

                            # Trouver fin méthode
                            method_indent = len(lines[method_start]) - len(lines[method_start].lstrip())
                            while method_end < len(lines):
                                line = lines[method_end]
                                if not line.strip() or line.strip().startswith('#'):
                                    method_end += 1
                                    continue
                                current_indent = len(line) - len(line.lstrip())
                                if current_indent <= method_indent:
                                    break
                                method_end += 1

                            method_code = '\n'.join(lines[method_start:method_end])

                            method = {
                                'name': body_node.name, 
                                'line': body_node.lineno,
                                'codeContent': method_code  # ✅ AJOUTÉ
                            }
                            class_info['methods'].append(method)

                    classes.append(class_info)

        except SyntaxError:
            # Fallback regex (sans codeContent pour simplicitĂ©)
            class_pattern = r'(?:@[\w\s]+\n)*\s*class\s+(\w+)(?:\s*\([^)]*\))?'
            for match in re.finditer(class_pattern, content, re.MULTILINE | re.DOTALL):
                classes.append({
                    'name': match.group(1),
                    'line': content[:match.start()].count('\n') + 1,
                    'methods': [],
                    'uid': f"class_{match.group(1)}_approx",
                    'uses_vars': [],
                    'codeContent': ""  # Vide pour fallback
                })

        return classes

    def extract_detailed_relations(self, content: str, file_path: str, 
                                   classes: List[Dict], functions: List[Dict]) -> Dict[str, List[Dict]]:

        relations = {
            'class_to_class': [],
            'class_to_function': [],
            'function_to_function': [],
            'function_to_class': []
        }

        ext = os.path.splitext(file_path)[1].lower()

        if ext == '.py':
            return self._extract_python_detailed_relations(content, classes, functions)
        elif ext == '.java':
            return self._extract_java_detailed_relations(content, classes, functions)
        elif ext in ['.js', '.jsx', '.ts', '.tsx']:
            return self._extract_js_detailed_relations(content, classes, functions)

        return relations

    def _extract_python_detailed_relations(self, content: str, 
                                          classes: List[Dict], 
                                          functions: List[Dict]) -> Dict[str, List[Dict]]:
        """
        ✅ Extrait relations détaillées pour Python avec AST
        ADAPTÉ AU SCHÉMA: utilise 'inherits' au lieu de 'extends' pour Python
        """
        relations = {
            'class_to_class': [],
            'class_to_function': [],
            'function_to_function': [],
            'function_to_class': []
        }

        try:
            tree = ast.parse(content)

            # Créer des mappings pour recherche rapide
            class_map = {cls['name']: cls for cls in classes}
            func_map = {func['name']: func for func in functions}

            # === RELATIONS CLASSE-CLASSE (Héritage) ===
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef):
                    source_class = class_map.get(node.name)
                    if not source_class:
                        continue

                    # ✅ Utiliser 'inherits' (conforme au schéma)
                    for base in node.bases:
                        if isinstance(base, ast.Name):
                            base_name = base.id
                            if base_name in class_map:
                                relations['class_to_class'].append({
                                    'source_uid': source_class['uid'],
                                    'source_name': node.name,
                                    'target_uid': class_map[base_name]['uid'],
                                    'target_name': base_name,
                                    'relation_type': 'inherits',  # ✅ Conforme schéma
                                    'line': node.lineno,
                                    'category': 'parsed',
                                    'intra_file': True
                                })

            # === RELATIONS CLASSE-FONCTION (Méthode → Fonction externe) ===
            for cls_data in classes:
                for method in cls_data.get('methods', []):
                    method_name = method.get('name')

                    # Trouver le nœud AST de la méthode
                    for node in ast.walk(tree):
                        if isinstance(node, ast.FunctionDef) and node.name == method_name:
                            # Chercher appels de fonctions externes
                            for child in ast.walk(node):
                                if isinstance(child, ast.Call):
                                    called_name = None

                                    if isinstance(child.func, ast.Name):
                                        called_name = child.func.id

                                    # Si c'est une fonction externe (pas une méthode)
                                    if called_name and called_name in func_map:
                                        relations['class_to_function'].append({
                                            'source_uid': method.get('uid'),
                                            'source_name': f"{cls_data['name']}.{method_name}",
                                            'target_uid': func_map[called_name]['uid'],
                                            'target_name': called_name,
                                            'relation_type': 'calls',  # ✅ Conforme schéma
                                            'line': child.lineno,
                                            'category': 'parsed',
                                            'intra_file': True
                                        })

            # === RELATIONS FONCTION-FONCTION ===
            for func_data in functions:
                func_name = func_data['name']

                # Trouver le nœud AST
                for node in ast.walk(tree):
                    if isinstance(node, ast.FunctionDef) and node.name == func_name:
                        # Chercher tous les appels
                        for child in ast.walk(node):
                            if isinstance(child, ast.Call):
                                called_name = None

                                if isinstance(child.func, ast.Name):
                                    called_name = child.func.id
                                elif isinstance(child.func, ast.Attribute):
                                    called_name = child.func.attr

                                # Si c'est une autre fonction
                                if called_name and called_name in func_map:
                                    relations['function_to_function'].append({
                                        'source_uid': func_data['uid'],
                                        'source_name': func_name,
                                        'target_uid': func_map[called_name]['uid'],
                                        'target_name': called_name,
                                        'relation_type': 'calls',  # ✅ Conforme schéma
                                        'line': child.lineno,
                                        'category': 'parsed',
                                        'intra_file': True
                                    })

            # === RELATIONS FONCTION-CLASSE (Instanciation) ===
            for func_data in functions:
                func_name = func_data['name']

                for node in ast.walk(tree):
                    if isinstance(node, ast.FunctionDef) and node.name == func_name:
                        # Chercher instanciations de classes
                        for child in ast.walk(node):
                            if isinstance(child, ast.Call):
                                if isinstance(child.func, ast.Name):
                                    class_name = child.func.id

                                    if class_name in class_map:
                                        relations['function_to_class'].append({
                                            'source_uid': func_data['uid'],
                                            'source_name': func_name,
                                            'target_uid': class_map[class_name]['uid'],
                                            'target_name': class_name,
                                            'relation_type': 'uses',  # ✅ Conforme schéma (uses pour instanciation)
                                            'line': child.lineno,
                                            'category': 'parsed',
                                            'intra_file': True
                                        })

        except Exception as e:
            logger.error(f"Erreur extraction relations détaillées Python: {e}")

        return relations

    def _extract_java_detailed_relations(self, content: str, 
                                         classes: List[Dict], 
                                         functions: List[Dict]) -> Dict[str, List[Dict]]:
        """
        ✅ Extrait relations détaillées pour Java avec regex
        ADAPTÉ AU SCHÉMA: utilise 'extends' et 'implements'
        """
        relations = {
            'class_to_class': [],
            'class_to_function': [],
            'function_to_function': [],
            'function_to_class': []
        }

        class_map = {cls['name']: cls for cls in classes}
        func_map = {func['name']: func for func in functions}

        # ✅ Héritage Java (extends)
        extends_pattern = r'class\s+(\w+)\s+extends\s+(\w+)'
        for match in re.finditer(extends_pattern, content):
            child_class = match.group(1)
            parent_class = match.group(2)

            if child_class in class_map and parent_class in class_map:
                relations['class_to_class'].append({
                    'source_uid': class_map[child_class]['uid'],
                    'source_name': child_class,
                    'target_uid': class_map[parent_class]['uid'],
                    'target_name': parent_class,
                    'relation_type': 'extends',  # ✅ Conforme schéma Java
                    'line': content[:match.start()].count('\n') + 1,
                    'category': 'parsed',
                    'intra_file': True
                })

        # ✅ Implémentation d'interfaces (implements)
        implements_pattern = r'class\s+(\w+)\s+implements\s+(\w+(?:\s*,\s*\w+)*)'
        for match in re.finditer(implements_pattern, content):
            class_name = match.group(1)
            interfaces = [i.strip() for i in match.group(2).split(',')]

            if class_name in class_map:
                for interface in interfaces:
                    if interface in class_map:
                        relations['class_to_class'].append({
                            'source_uid': class_map[class_name]['uid'],
                            'source_name': class_name,
                            'target_uid': class_map[interface]['uid'],
                            'target_name': interface,
                            'relation_type': 'implements',  # ✅ Conforme schéma
                            'line': content[:match.start()].count('\n') + 1,
                            'category': 'parsed',
                            'intra_file': True
                        })

        # Appels de méthodes (simplifié)
        call_pattern = r'(\w+)\s*\.\s*(\w+)\s*\('
        for match in re.finditer(call_pattern, content):
            method_name = match.group(2)

            if method_name in func_map:
                relations['function_to_function'].append({
                    'source_uid': '',  # Sera résolu plus tard
                    'source_name': '',
                    'target_uid': func_map[method_name]['uid'],
                    'target_name': method_name,
                    'relation_type': 'calls',  # ✅ Conforme schéma
                    'line': content[:match.start()].count('\n') + 1,
                    'category': 'parsed',
                    'intra_file': True
                })

        return relations

